Подождите, это становится сложно. Давайте упрощу и сделаю проще.

Подход без `FutureBuilder` для пагинации — просто использовать `ValueListenableBuilder`:

1. При загрузке страницы 0: `_filteredCurrenciesNotifier.value = []`, потом загружаем и обновляем.
2. Кнопка «Показать ещё»: загружает следующую страницу, добавляет к списку через `notifier.value += newItems`.
3. При возврате на экран: сброс notifier и перезагрузка с base='USD'.

Но FutureBuilder нужен для отображения индикатора загрузки при первой загрузке... Или я могу использовать `ValueListenableBuilder` всегда.

Давайте перепишу проще:

```dart
class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  int _currentPage = 0;
  static const int _pageSize = 20;

  bool _isLoadingFirstPage = true;

  List<CurrencyModel> _allCurrencies = [];

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _loadPage(0, isReset: true);
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      _resetAndReload();
    }
  }

  Future<void> _loadPage(int page, {bool isReset = false}) async {
    final currencyRepository = context.read<CurrencyRepository>();

    if (isReset || page == 0) {
      setState(() {
        _allCurrencies = [];
        _filteredCurrenciesNotifier.value = [];
        _isLoadingFirstPage = true;
      });
    }

    try {
      final CurrencyPage pageData = await currencyRepository.fetchRates(
        CurrencyPageRequest(base: 'USD', page: page, pageSize: _pageSize),
      );

      setState(() {
        if (page == 0) {
          _allCurrencies = pageData.items;
        } else {
          _allCurrencies.addAll(pageData.items);
        }

        _filteredCurrenciesNotifier.value = List.from(_allCurrencies);
        _isLoadingFirstPage = false;

        if (isReset || page == 0) {
          currencyRepository.saveCurrencyList(_allCurrencies);
          _fadeController.forward();
        }
      });
    } catch (_) {
      setState(() => _isLoadingFirstPage = false);
    }
  }

  void _loadMore() async {
    final nextPage = _currentPage + 1;
    setState(() {
      _currentPage = nextPage;
    });
    await _loadPage(nextPage);
  }

  void _resetAndReload() {
    setState(() {
      _currentPage = 0;
    });
    _filteredCurrenciesNotifier.value = [];
    _loadPage(0, isReset: true);
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: ValueListenableBuilder<List<CurrencyModel>>(
        valueListenable: _filteredCurrenciesNotifier,
        builder: (BuildContext context, List<CurrencyModel> data, _) {
          if (_isLoadingFirstPage) return const Center(child: CircularProgressIndicator());

          if (data.isEmpty) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ListView.builder(
                    itemCount: data.length + (_hasMore ? 1 : 0), // +1 для кнопки "Показать ещё"
                    itemBuilder: (BuildContext context, int index) {
                      if (index == data.length && _hasMore) {
                        return Padding(
                          padding: const EdgeInsets.all(20),
                          child: Center(
                            child: ElevatedButton(
                              onPressed: _loadMore,
                              child: Text(context.loc.showMore), // Нужно добавить в l10n
                            ),
                          ),
                        );
                      }

                      final CurrencyModel currency = data[index];

                      return Padding(
                        key: ValueKey(currency.id),
                        padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                        child: CurrencyCard(model: currency),
                      );
                    },
                    padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }

  bool get _hasMore => !_isLoadingFirstPage && ... // Нужно хранить hasMorePages
}
```

