import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  final List<CurrencyModel> _allCurrencies = [];

  late final AnimationController _fadeController;

  late Future<void> _loadFuture;

  int _currentPage = 0;
  bool _hasMore = true;
  bool _isLoadingMore = false;

  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _loadFuture = _fetchInitial();
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    _refreshOnRegainFocus();
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      _refreshOnRegainFocus();
    }
  }

  Future<void> _fetchInitial() async {
    final currencyRepository = context.read<CurrencyRepository>();

    setState(() {
      _allCurrencies.clear();
      _currentPage = 0;
      _hasMore = true;
    });

    await _fetchPage(currencyRepository, append: false);
    if (mounted) {
      _fadeController.forward();
    }
  }

  Future<void> _fetchPage(CurrencyRepository repository, {required bool append}) async {
    if (_isLoadingMore) return;

    setState(() => _isLoadingMore = true);

    try {
      final CurrencyPage page = await repository.fetchRates(
        CurrencyPageRequest(base: 'USD', page: _currentPage, pageSize: 20),
      );

      if (!mounted) return;

      setState(() {
        if (append) {
          _allCurrencies.addAll(page.items);
        } else {
          _allCurrencies.clear();
          _allCurrencies.addAll(page.items);
        }
        _currentPage = page.page + 1;
        _hasMore = page.hasMore;
      });
    } finally {
      if (mounted) {
        setState(() => _isLoadingMore = false);
      }
    }
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  void _refreshOnRegainFocus() {
    if (mounted && !_isLoadingMore) {
      setState(() {
        _allCurrencies.clear();
        _currentPage = 0;
        _hasMore = true;
        _filteredCurrenciesNotifier.value = [];
      });
      _loadFuture = _fetchInitial();
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder<void>(
        future: _loadFuture,
        builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
          if (snapshot.connectionState != ConnectionState.done) {
            return const Center(child: CircularProgressIndicator());
          }

          final List<CurrencyModel>? data = snapshot.data == null ? [] : _filteredCurrenciesNotifier.value;

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                if (_hasMore) ...[
                  SizedBox(height: 8),
                  Center(
                    child: TextButton(
                      onPressed: () {
                        final repo = context.read<CurrencyRepository>();
                        _fetchPage(repo, append: true);
                      },
                      child: Padding(
                        padding: const EdgeInsets.symmetric(vertical: 8.0),
                        child: Text(context.loc.showMore),
                      ),
                    ),
                  ),
                ] else if (_isLoadingMore) ...[
                  SizedBox(height: 8),
                  Center(child: CircularProgressIndicator()),
                ],
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> data, _) {
                      return ListView.builder(
                        itemCount: data.length,
                        itemBuilder: (BuildContext context, int index) {
                          final CurrencyModel currency = data[index];

                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0 ? const EdgeInsets.fromLTRB(22, 20, 22, 10) : const EdgeInsets.symmetric(horizontal: 22, vertical: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                      ),
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}

